export * from './use-knowledge-base.js';
export * from './use-knowledge-base-document.js';
export * from './use-knowledge-base-segment.js';

import { useCallback, useEffect, useRef, useState } from 'react';
import type { KnowledgeBaseService } from '../providers/service/knowledge-base.js';

const serviceIds = new WeakMap<object, number>();
let nextServiceId = 1;

/** Preserves injected service identity inside request keys without serializing its methods. */
export const getKnowledgeBaseServiceKey = (service: object) => {
  const known = serviceIds.get(service);
  if (known) return known;
  const id = nextServiceId++;
  serviceIds.set(service, id);
  return id;
};

export const serviceKey = (service: KnowledgeBaseService | undefined) =>
  service ? getKnowledgeBaseServiceKey(service) : 'unconfigured';

export type AsyncState<T> = {
  data?: T;
  error?: unknown;
  loading: boolean;
  retry: () => void;
};

/** Drops old responses and clears previous data when a logical resource changes. */
export function useRequest<T>(
  key: unknown,
  request: (signal: AbortSignal) => Promise<T>,
  enabled = true,
): AsyncState<T> {
  const sequence = useRef(0);
  const [state, setState] = useState<Omit<AsyncState<T>, 'retry'>>({
    loading: enabled,
  });
  const [attempt, setAttempt] = useState(0);
  const retry = useCallback(() => setAttempt((value) => value + 1), []);
  // Logical values, not freshly allocated arrays/objects, drive this lifecycle.
  const logicalKey = JSON.stringify(key);

  useEffect(() => {
    if (!enabled) {
      setState({ loading: false });
      return;
    }

    const controller = new AbortController();
    const id = ++sequence.current;
    // Never let a prior base, document, segment, or retrieval result render as current.
    setState({ loading: true });

    void request(controller.signal).then(
      (data) => {
        if (sequence.current === id && !controller.signal.aborted) {
          setState({ data, loading: false });
        }
      },
      (error) => {
        if (sequence.current === id && !controller.signal.aborted) {
          setState({ error, loading: false });
        }
      },
    );

    return () => controller.abort();
    // request is intentionally keyed by logicalKey so render-created callbacks cannot restart it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attempt, enabled, logicalKey]);

  return { ...state, retry };
}

import { useMemo } from 'react';
import { useKnowledgeBaseService } from '../providers/context.js';
import type { KnowledgeBaseService } from '../providers/service/knowledge-base.js';
import type { RecordId } from '../providers/types.js';
import { serviceKey, useRequest } from './shared.js';

type PaginatedDocumentRequest = {
  knowledgeBaseKey: string;
  page: number;
  pageSize: number;
  query?: string;
};

function useAllKnowledgeBaseDocuments(
  knowledgeBaseKey: string | undefined,
  service: KnowledgeBaseService | undefined,
) {
  return useRequest(
    ['documents', knowledgeBaseKey, 'all', serviceKey(service)],
    (signal) =>
      service!.listDocuments({
        mode: 'all',
        knowledgeBaseKey: knowledgeBaseKey!,
        signal,
      }),
    !!service && !!knowledgeBaseKey,
  );
}

function usePaginatedKnowledgeBaseDocuments(
  request: PaginatedDocumentRequest | undefined,
  service: KnowledgeBaseService | undefined,
) {
  const key = useMemo(
    () => [
      'documents',
      request?.knowledgeBaseKey,
      request?.page,
      request?.pageSize,
      request?.query,
      serviceKey(service),
    ],
    [
      request?.knowledgeBaseKey,
      request?.page,
      request?.pageSize,
      request?.query,
      service,
    ],
  );
  return useRequest(
    key,
    (signal) => service!.listDocuments({ mode: 'server', ...request!, signal }),
    !!service && !!request?.knowledgeBaseKey,
  );
}

function useKnowledgeBaseDocumentRequest(
  request: { knowledgeBaseKey: string; documentId: RecordId } | undefined,
  service: KnowledgeBaseService | undefined,
) {
  return useRequest(
    [
      'document',
      request?.knowledgeBaseKey,
      request?.documentId,
      serviceKey(service),
    ],
    (signal) => service!.getDocument({ ...request!, signal }),
    !!service &&
      !!request?.knowledgeBaseKey &&
      request?.documentId !== undefined,
  );
}

export type KnowledgeBaseDocumentsOptions = {
  mode?: 'all' | 'paginated';
  page?: number;
  pageSize?: number;
  query?: string;
  enabled?: boolean;
};

export type UseKnowledgeBaseDocumentOptions = {
  knowledgeBaseKey?: string;
  documentId?: RecordId;
  documents?: KnowledgeBaseDocumentsOptions;
  document?: { enabled?: boolean };
  upload?: {
    enabled?: boolean;
    includeConstraints?: boolean;
    includeZipEncodingOptions?: boolean;
  };
};

/** Document-level state: document lists, one document, and upload metadata. */
export function useKnowledgeBaseDocument(
  options: UseKnowledgeBaseDocumentOptions = {},
) {
  const service = useKnowledgeBaseService();
  const knowledgeBaseKey = options.knowledgeBaseKey;
  const documentsMode = options.documents?.mode;
  const documentsEnabled =
    options.documents?.enabled !== false && !!knowledgeBaseKey;
  const documentsAll = useAllKnowledgeBaseDocuments(
    documentsMode === 'all' && documentsEnabled ? knowledgeBaseKey : undefined,
    documentsMode === 'all' && documentsEnabled ? service : undefined,
  );
  const documentsPaginated = usePaginatedKnowledgeBaseDocuments(
    documentsMode === 'paginated' && documentsEnabled
      ? {
          knowledgeBaseKey: knowledgeBaseKey,
          page: options.documents?.page ?? 1,
          pageSize: options.documents?.pageSize ?? 20,
          query: options.documents?.query,
        }
      : undefined,
    documentsMode === 'paginated' && documentsEnabled ? service : undefined,
  );
  const documentEnabled =
    options.document?.enabled !== false &&
    !!knowledgeBaseKey &&
    options.documentId !== undefined;
  const document = useKnowledgeBaseDocumentRequest(
    documentEnabled
      ? { knowledgeBaseKey: knowledgeBaseKey, documentId: options.documentId! }
      : undefined,
    documentEnabled ? service : undefined,
  );
  const uploadEnabled = options.upload?.enabled !== false && !!knowledgeBaseKey;
  const includeConstraints =
    options.upload?.includeConstraints ?? options.upload !== undefined;
  const includeZipEncodingOptions =
    options.upload?.includeZipEncodingOptions === true;
  const uploadConstraints = useRequest(
    ['upload-constraints', knowledgeBaseKey, serviceKey(service)],
    (signal) =>
      service.getUploadConstraints({
        knowledgeBaseKey: knowledgeBaseKey!,
        signal,
      }),
    uploadEnabled && includeConstraints,
  );
  const zipEncodingOptions = useRequest(
    ['zip-encoding-options', knowledgeBaseKey, serviceKey(service)],
    (signal) =>
      service.getZipFilenameEncodingOptions({
        knowledgeBaseKey: knowledgeBaseKey!,
        signal,
      }),
    uploadEnabled && includeZipEncodingOptions,
  );

  return {
    service,
    documents: {
      all: documentsAll,
      paginated: documentsPaginated,
    },
    document,
    upload: {
      constraints: uploadConstraints,
      zipEncodingOptions,
    },
  };
}

import { useKnowledgeBaseService } from '../providers/context.js';
import type { KnowledgeBaseService } from '../providers/service/knowledge-base.js';
import type { RecordId, SegmentRequest } from '../providers/types.js';
import { serviceKey, useRequest } from './shared.js';

type PaginatedSegmentRequest = {
  knowledgeBaseKey: string;
  documentId: RecordId;
  page: number;
  pageSize: number;
  keyword?: string;
  enabled?: boolean;
};

function useKnowledgeBaseSegmentsRequest(
  request: PaginatedSegmentRequest | undefined,
  service: KnowledgeBaseService | undefined,
) {
  return useRequest(
    [
      'segments',
      request?.knowledgeBaseKey,
      request?.documentId,
      request?.page,
      request?.pageSize,
      request?.keyword,
      request?.enabled,
      serviceKey(service),
    ],
    (signal) => service!.listSegments({ mode: 'server', ...request!, signal }),
    !!service &&
      !!request?.knowledgeBaseKey &&
      request?.documentId !== undefined,
  );
}

function useKnowledgeBaseSegmentRequest(
  request: SegmentRequest | undefined,
  service: KnowledgeBaseService | undefined,
) {
  return useRequest(
    [
      'segment',
      request?.knowledgeBaseKey,
      request?.documentId,
      request?.segmentUid,
      serviceKey(service),
    ],
    (signal) => service!.getSegment({ ...request!, signal }),
    !!service &&
      !!request?.knowledgeBaseKey &&
      request?.documentId !== undefined &&
      !!request?.segmentUid,
  );
}

export type KnowledgeBaseSegmentsOptions = {
  page?: number;
  pageSize?: number;
  keyword?: string;
  enabledOnly?: boolean;
  enabled?: boolean;
};

export type UseKnowledgeBaseSegmentOptions = {
  knowledgeBaseKey?: string;
  documentId?: RecordId;
  segmentUid?: string;
  segments?: KnowledgeBaseSegmentsOptions;
  segment?: { enabled?: boolean };
};

/** Segment-level state: segment list and one segment. */
export function useKnowledgeBaseSegment(
  options: UseKnowledgeBaseSegmentOptions = {},
) {
  const service = useKnowledgeBaseService();
  const knowledgeBaseKey = options.knowledgeBaseKey;
  const documentId = options.documentId;
  const segmentsEnabled =
    options.segments?.enabled !== false &&
    !!knowledgeBaseKey &&
    documentId !== undefined;
  const segments = useKnowledgeBaseSegmentsRequest(
    segmentsEnabled
      ? {
          knowledgeBaseKey: knowledgeBaseKey,
          documentId: documentId,
          page: options.segments?.page ?? 1,
          pageSize: options.segments?.pageSize ?? 20,
          keyword: options.segments?.keyword,
          enabled: options.segments?.enabledOnly ? true : undefined,
        }
      : undefined,
    segmentsEnabled ? service : undefined,
  );
  const segmentEnabled =
    options.segment?.enabled !== false &&
    !!knowledgeBaseKey &&
    documentId !== undefined &&
    !!options.segmentUid;
  const segment = useKnowledgeBaseSegmentRequest(
    segmentEnabled
      ? {
          knowledgeBaseKey: knowledgeBaseKey,
          documentId: documentId,
          segmentUid: options.segmentUid!,
        }
      : undefined,
    segmentEnabled ? service : undefined,
  );

  return { service, segments, segment };
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useKnowledgeBaseService } from '../providers/context.js';
import type { KnowledgeBaseService } from '../providers/service/knowledge-base.js';
import type { KnowledgeBase, RetrievalRequest } from '../providers/types.js';
import { serviceKey, useRequest } from './shared.js';

function useAllKnowledgeBases(service: KnowledgeBaseService | undefined) {
  return useRequest(
    ['knowledge-bases', 'all', serviceKey(service)],
    (signal) => service!.listKnowledgeBases({ mode: 'all', signal }),
    !!service,
  );
}

function usePaginatedKnowledgeBases(
  request: { page: number; pageSize: number; query?: string },
  service: KnowledgeBaseService | undefined,
) {
  const key = useMemo(
    () => [
      'knowledge-bases',
      request.page,
      request.pageSize,
      request.query,
      serviceKey(service),
    ],
    [request.page, request.pageSize, request.query, service],
  );
  return useRequest(
    key,
    (signal) =>
      service!.listKnowledgeBases({ mode: 'server', ...request, signal }),
    !!service,
  );
}

type InfiniteKnowledgeBaseRequest = {
  pageSize: number;
  query?: string;
};

/** Accumulates server pages for card directories while keeping query/service changes stale-safe. */
function useInfiniteKnowledgeBases(
  request: InfiniteKnowledgeBaseRequest,
  service: KnowledgeBaseService | undefined,
) {
  const [page, setPage] = useState(1);
  const [rows, setRows] = useState<KnowledgeBase[]>([]);
  const [count, setCount] = useState<number>();
  const resetKey = useMemo(
    () =>
      JSON.stringify([
        serviceKey(service),
        request.pageSize,
        request.query ?? '',
      ]),
    [request.pageSize, request.query, service],
  );
  const resetKeyRef = useRef(resetKey);
  const resetPending = resetKeyRef.current !== resetKey;
  const loadMoreLock = useRef(false);
  const result = usePaginatedKnowledgeBases(
    { page, pageSize: request.pageSize, query: request.query },
    service,
  );

  useEffect(() => {
    if (!resetPending) return;
    resetKeyRef.current = resetKey;
    loadMoreLock.current = false;
    setPage(1);
    setRows([]);
    setCount(undefined);
  }, [resetKey, resetPending]);

  useEffect(() => {
    const data = result.data;
    if (resetPending || !data) return;
    setCount(data.count);
    setRows((currentRows) => {
      if (page === 1) return data.rows;
      const knownIds = new Set(currentRows.map((item) => item.id));
      const nextRows = data.rows.filter((item) => {
        if (knownIds.has(item.id)) return false;
        knownIds.add(item.id);
        return true;
      });
      return [...currentRows, ...nextRows];
    });
  }, [page, resetPending, result.data]);

  useEffect(() => {
    if (!result.loading) loadMoreLock.current = false;
  }, [result.loading]);

  const visibleRows = resetPending ? [] : rows;
  const visibleCount = resetPending ? undefined : count;
  const hasMore =
    visibleCount !== undefined && visibleRows.length < visibleCount;
  const loadMore = useCallback(() => {
    if (!hasMore || result.loading || result.error || loadMoreLock.current)
      return;
    loadMoreLock.current = true;
    setPage((currentPage) => currentPage + 1);
  }, [hasMore, result.error, result.loading]);

  return {
    rows: visibleRows,
    count: visibleCount ?? visibleRows.length,
    loading: resetPending || (result.loading && visibleRows.length === 0),
    loadingMore: !resetPending && result.loading && visibleRows.length > 0,
    error: resetPending ? undefined : result.error,
    hasMore,
    loadMore,
    retry: result.retry,
  };
}

function useKnowledgeBaseRetrieval(
  request: RetrievalRequest | undefined,
  service: KnowledgeBaseService | undefined,
) {
  return useRequest(
    [
      'retrieval',
      request?.knowledgeBaseKey,
      request?.query,
      request?.topK,
      request?.score,
      serviceKey(service),
    ],
    (signal) => service!.runRetrieval({ ...request!, signal }),
    !!service && !!request?.knowledgeBaseKey && !!request?.query.trim(),
  );
}

export type KnowledgeBaseDirectoryOptions = {
  mode?: 'all' | 'paginated' | 'infinite';
  page?: number;
  pageSize?: number;
  query?: string;
  enabled?: boolean;
};

export type UseKnowledgeBaseOptions = {
  knowledgeBaseKey?: string;
  knowledgeBase?: KnowledgeBase;
  directory?: KnowledgeBaseDirectoryOptions;
  retrieval?: Omit<RetrievalRequest, 'knowledgeBaseKey' | 'signal'> & {
    enabled?: boolean;
  };
};

/** Knowledge-base-level state: directory, detail, and retrieval. */
export function useKnowledgeBase(options: UseKnowledgeBaseOptions = {}) {
  const service = useKnowledgeBaseService();
  const suppliedKnowledgeBase = options.knowledgeBase;
  const knowledgeBaseKey =
    suppliedKnowledgeBase?.key ?? options.knowledgeBaseKey;
  const directoryMode = options.directory?.mode;
  const directoryEnabled = options.directory?.enabled !== false;
  const directoryPage = options.directory?.page ?? 1;
  const directoryPageSize = options.directory?.pageSize ?? 20;
  const directoryQuery = options.directory?.query;
  const directoryAll = useAllKnowledgeBases(
    directoryMode === 'all' && directoryEnabled ? service : undefined,
  );
  const directoryPaginated = usePaginatedKnowledgeBases(
    { page: directoryPage, pageSize: directoryPageSize, query: directoryQuery },
    directoryMode === 'paginated' && directoryEnabled ? service : undefined,
  );
  const directoryInfinite = useInfiniteKnowledgeBases(
    { pageSize: directoryPageSize, query: directoryQuery },
    directoryMode === 'infinite' && directoryEnabled ? service : undefined,
  );

  const requestedDetail = useRequest(
    ['knowledge-base', knowledgeBaseKey, serviceKey(service)],
    (signal) => service.getKnowledgeBase(knowledgeBaseKey!, signal),
    !!knowledgeBaseKey && !suppliedKnowledgeBase,
  );
  const detail = suppliedKnowledgeBase
    ? {
        data: suppliedKnowledgeBase,
        loading: false,
        retry: requestedDetail.retry,
      }
    : requestedDetail;
  const retrievalEnabled =
    options.retrieval?.enabled !== false &&
    !!detail.data?.key &&
    !!options.retrieval?.query.trim();
  const retrieval = useKnowledgeBaseRetrieval(
    retrievalEnabled
      ? {
          knowledgeBaseKey: detail.data!.key,
          query: options.retrieval!.query,
          topK: options.retrieval?.topK,
          score: options.retrieval?.score,
        }
      : undefined,
    retrievalEnabled ? service : undefined,
  );

  return {
    service,
    knowledgeBase: detail,
    directory: {
      all: directoryAll,
      paginated: directoryPaginated,
      infinite: directoryInfinite,
    },
    retrieval,
  };
}

import { createContext, useContext, type ReactNode } from 'react';
import { knowledgeBaseService } from './service/index.js';
import type { KnowledgeBaseService } from './service/knowledge-base.js';

const KnowledgeBaseServiceContext =
  createContext<KnowledgeBaseService>(knowledgeBaseService);

/**
 * The Knowledge base workspace uses the permission-guide-compliant NocoBase resource-client
 * implementation by default. Applications may provide this context to replace it
 * with a version-locked proxy or a test service without changing the UI routes.
 */
export function KnowledgeBaseServiceProvider({
  service,
  children,
}: {
  service: KnowledgeBaseService;
  children: ReactNode;
}) {
  return (
    <KnowledgeBaseServiceContext.Provider value={service}>
      {children}
    </KnowledgeBaseServiceContext.Provider>
  );
}

export function useKnowledgeBaseService() {
  return useContext(KnowledgeBaseServiceContext);
}

export * from './types.js';
export * from './utils.js';
export * from './context.js';
export * from './service/index.js';

import { nocobaseClient } from '@nocobase/app-portal-sdk/client';
import { createKnowledgeBaseService } from './knowledge-base-factory.js';

export {
  createKnowledgeBaseService,
  normalizeKnowledgeBaseMutation,
  normalizeVectorDatabaseMutation,
} from './knowledge-base-factory.js';

/** The default Knowledge base workspace integration for compatible user-side Knowledge Base actions. */
export const knowledgeBaseService = createKnowledgeBaseService(nocobaseClient);

import { normalizePagedResult, type PagedResult } from '../utils.js';
import type { KnowledgeBaseService } from './knowledge-base.js';
import type {
  KnowledgeBase,
  KnowledgeBaseManagementOption,
  KnowledgeBaseManagementOptions,
  KnowledgeBaseMutation,
  VectorDatabase,
  VectorDatabaseMutation,
  VectorDatabaseProvider,
  KnowledgeBaseDocument,
  KnowledgeBaseSearchResult,
  KnowledgeBaseSegment,
  KnowledgeBaseSegmentOptions,
  KnowledgeBaseSegmentQuestion,
  UploadConstraints,
  UploadResult,
  ZipFilenameEncodingOption,
} from '../types.js';

/**
 * The AI Knowledge Base plugin's user-side actions apply role association,
 * record ownership, LOCAL-write, and server response allowlist policies. This
 * adapter is a complete Portal example for that contract, not an adapter for
 * administrator-only vector-store or knowledge-base configuration actions.
 */
type ActionOptions = {
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE';
  query?: Record<
    string,
    string | number | boolean | Array<string | number | boolean> | undefined
  >;
  body?: unknown;
  signal?: AbortSignal;
  unwrap?: 'data' | 'deep-data' | 'none';
};
type NocoBaseKnowledgeBaseClient = {
  action<T>(
    resource: string,
    action: string,
    options?: ActionOptions,
  ): Promise<T>;
};
type UnknownRecord = Record<string, unknown>;
type UploadStorage = {
  disk: string;
  type?: string;
  maxFileSizeBytes?: number;
};

const supportedExtensions = ['.doc', '.docx', '.md', '.pdf', '.txt', '.zip'];

const isRecord = (value: unknown): value is UnknownRecord =>
  !!value && typeof value === 'object' && !Array.isArray(value);

const responseData = (value: unknown) =>
  isRecord(value) && 'data' in value ? value.data : value;

const text = (value: unknown) =>
  typeof value === 'string' ? value : undefined;
const number = (value: unknown) =>
  typeof value === 'number' && Number.isFinite(value) ? value : undefined;
const boolean = (value: unknown) => {
  if (typeof value === 'boolean') return value;
  if (value === 1) return true;
  if (value === 0) return false;
  return undefined;
};
const recordId = (value: unknown) =>
  typeof value === 'string' || typeof value === 'number' ? value : undefined;

const required = <T>(value: T | undefined, field: string): T => {
  if (value === undefined) {
    throw new Error(
      `Knowledge Base API response is missing required field: ${field}.`,
    );
  }
  return value;
};

const optionalDate = (value: unknown) => text(value);

function toSegmentOptions(
  value: unknown,
): KnowledgeBaseSegmentOptions | undefined {
  const item = isRecord(value) ? value : {};
  const chunkSize = number(item.chunkSize);
  const chunkOverlap = number(item.chunkOverlap);
  const options: KnowledgeBaseSegmentOptions = {
    ...(boolean(item.enabled) !== undefined
      ? { enabled: boolean(item.enabled) }
      : {}),
    ...(chunkSize !== undefined && chunkSize > 0 ? { chunkSize } : {}),
    ...(chunkOverlap !== undefined && chunkOverlap >= 0
      ? { chunkOverlap }
      : {}),
  };
  return Object.keys(options).length ? options : undefined;
}

function toKnowledgeBase(value: unknown): KnowledgeBase {
  const item = isRecord(value) ? value : {};
  const knowledgeBaseType = text(item.knowledgeBaseType);
  if (
    knowledgeBaseType !== 'LOCAL' &&
    knowledgeBaseType !== 'READONLY' &&
    knowledgeBaseType !== 'EXTERNAL'
  ) {
    throw new Error(
      'Knowledge Base API response has an invalid knowledgeBaseType.',
    );
  }
  return {
    id: required(recordId(item.id), 'id'),
    key: required(text(item.key), 'key'),
    name: required(text(item.name), 'name'),
    knowledgeBaseType: knowledgeBaseType,
    enabled: required(boolean(item.enabled), 'enabled'),
    ...(text(item.vectorStoreProvider)
      ? { vectorStoreProvider: text(item.vectorStoreProvider) }
      : {}),
    ...(text(item.vectorStoreConfigKey)
      ? { vectorStoreConfigKey: text(item.vectorStoreConfigKey) }
      : {}),
    ...(text(item.vectorDatabaseKey)
      ? { vectorDatabaseKey: text(item.vectorDatabaseKey) }
      : {}),
    ...(text(item.disk) ? { disk: text(item.disk) } : {}),
    ...(text(item.llmService) ? { llmService: text(item.llmService) } : {}),
    ...(text(item.embeddingModel)
      ? { embeddingModel: text(item.embeddingModel) }
      : {}),
    ...(toSegmentOptions(item.segmentOptions)
      ? { segmentOptions: toSegmentOptions(item.segmentOptions) }
      : {}),
    ...(text(item.description) ? { description: text(item.description) } : {}),
    ...(number(item.documentCount) !== undefined
      ? { documentCount: number(item.documentCount) }
      : {}),
    ...(number(item.characterCount) !== undefined
      ? { characterCount: number(item.characterCount) }
      : {}),
    ...(number(item.aiEmployeeCount) !== undefined
      ? { aiEmployeeCount: number(item.aiEmployeeCount) }
      : {}),
    ...(optionalDate(item.createdAt)
      ? { createdAt: optionalDate(item.createdAt) }
      : {}),
    ...(optionalDate(item.updatedAt)
      ? { updatedAt: optionalDate(item.updatedAt) }
      : {}),
  };
}

function toDocument(value: unknown): KnowledgeBaseDocument {
  const item = isRecord(value) ? value : {};
  const segmentOptions = toSegmentOptions(item.segmentOptions);
  return {
    id: required(recordId(item.id), 'document.id'),
    knowledgeBaseKey: required(
      text(item.knowledgeBaseKey),
      'document.knowledgeBaseKey',
    ),
    ...(text(item.key) ? { key: text(item.key) } : {}),
    ...(text(item.title) ? { title: text(item.title) } : {}),
    ...(text(item.filename) ? { filename: text(item.filename) } : {}),
    ...(text(item.extname) ? { extname: text(item.extname) } : {}),
    ...(number(item.size) !== undefined ? { size: number(item.size) } : {}),
    ...(text(item.mimetype) ? { mimetype: text(item.mimetype) } : {}),
    ...(text(item.url) ? { url: text(item.url) } : {}),
    ...(text(item.preview) ? { preview: text(item.preview) } : {}),
    ...(number(item.characterCount) !== undefined
      ? { characterCount: number(item.characterCount) }
      : {}),
    ...(number(item.segmentCount) !== undefined
      ? { segmentCount: number(item.segmentCount) }
      : {}),
    ...(segmentOptions ? { segmentOptions } : {}),
    ...(text(item.segmentStatus)
      ? { segmentStatus: text(item.segmentStatus) }
      : {}),
    ...(text(item.segmentErrorMessage)
      ? { segmentErrorMessage: text(item.segmentErrorMessage) }
      : {}),
    ...(optionalDate(item.segmentUpdatedAt)
      ? { segmentUpdatedAt: optionalDate(item.segmentUpdatedAt) }
      : {}),
    ...(boolean(item.enabled) !== undefined
      ? { enabled: boolean(item.enabled) }
      : {}),
    ...(text(item.indexStatus) ? { indexStatus: text(item.indexStatus) } : {}),
    ...(text(item.errorMessage)
      ? { errorMessage: text(item.errorMessage) }
      : {}),
    ...(item.accessAbility === 'readOnly' || item.accessAbility === 'readWrite'
      ? { accessAbility: item.accessAbility }
      : {}),
    ...(recordId(item.createdById) !== undefined
      ? { createdById: recordId(item.createdById) }
      : {}),
    ...(optionalDate(item.createdAt)
      ? { createdAt: optionalDate(item.createdAt) }
      : {}),
    ...(optionalDate(item.updatedAt)
      ? { updatedAt: optionalDate(item.updatedAt) }
      : {}),
  };
}

function toQuestion(value: unknown): KnowledgeBaseSegmentQuestion | undefined {
  const item = isRecord(value) ? value : {};
  const content = text(item.content);
  if (!content) return undefined;
  return {
    content,
    ...(recordId(item.id) !== undefined ? { id: recordId(item.id) } : {}),
    ...(boolean(item.enabled) !== undefined
      ? { enabled: boolean(item.enabled) }
      : {}),
    ...(text(item.hash) ? { hash: text(item.hash) } : {}),
  };
}

function toSegment(value: unknown): KnowledgeBaseSegment {
  const item = isRecord(value) ? value : {};
  const questions = Array.isArray(item.questions)
    ? item.questions
        .map(toQuestion)
        .filter(
          (question): question is KnowledgeBaseSegmentQuestion => !!question,
        )
    : undefined;
  return {
    uid: required(text(item.uid), 'segment.uid'),
    ...(number(item.position) !== undefined
      ? { position: number(item.position) }
      : {}),
    ...(text(item.title) ? { title: text(item.title) } : {}),
    ...(text(item.preview) ? { preview: text(item.preview) } : {}),
    ...(text(item.content) ? { content: text(item.content) } : {}),
    ...(number(item.charLength) !== undefined
      ? { charLength: number(item.charLength) }
      : {}),
    ...(number(item.questionCount) !== undefined
      ? { questionCount: number(item.questionCount) }
      : {}),
    ...(boolean(item.enabled) !== undefined
      ? { enabled: boolean(item.enabled) }
      : {}),
    ...(text(item.contentHash) ? { contentHash: text(item.contentHash) } : {}),
    ...(optionalDate(item.updatedAt)
      ? { updatedAt: optionalDate(item.updatedAt) }
      : {}),
    ...(questions ? { questions } : {}),
  };
}

function toSearchResult(value: unknown): KnowledgeBaseSearchResult {
  const item = isRecord(value) ? value : {};
  return {
    ...(recordId(item.id) !== undefined ? { id: recordId(item.id) } : {}),
    ...(text(item.title) ? { title: text(item.title) } : {}),
    ...(text(item.filename) ? { filename: text(item.filename) } : {}),
    ...(text(item.content) ? { content: text(item.content) } : {}),
    ...(number(item.score) !== undefined ? { score: number(item.score) } : {}),
    ...(Array.isArray(item.matchedQuestions)
      ? {
          matchedQuestions: item.matchedQuestions.filter(
            (question): question is string => typeof question === 'string',
          ),
        }
      : {}),
  };
}
function toProviderFields(value: unknown): VectorDatabaseProvider['fields'] {
  if (!Array.isArray(value)) return undefined;
  const fields = value.flatMap((candidate) => {
    const item = isRecord(candidate) ? candidate : {};
    const key = text(item.key) ?? text(item.name);
    if (!key) return [];
    const fieldType = text(item.type) as
      'string' | 'number' | 'password' | 'boolean' | undefined;
    return [
      {
        key,
        ...(text(item.label) ? { label: text(item.label) } : {}),
        ...(fieldType ? { type: fieldType } : {}),
        ...(boolean(item.required) !== undefined
          ? { required: boolean(item.required) }
          : {}),
        ...('defaultValue' in item ? { defaultValue: item.defaultValue } : {}),
      },
    ];
  });
  return fields.length ? fields : undefined;
}

function toVectorDatabaseProvider(
  value: unknown,
): VectorDatabaseProvider | undefined {
  const item = isRecord(value) ? value : {};
  const name = text(item.name);
  const spec = text(item.spec);
  if (!name || !spec) return undefined;
  const fields = toProviderFields(item.fields ?? item.connectProps);
  return { name, spec, ...(fields ? { fields } : {}) };
}

function toVectorDatabase(value: unknown): VectorDatabase {
  const item = isRecord(value) ? value : {};
  return {
    id: required(recordId(item.id), 'vectorDatabase.id'),
    key: required(text(item.key), 'vectorDatabase.key'),
    name: required(text(item.name), 'vectorDatabase.name'),
    databaseSpec: required(
      text(item.databaseSpec),
      'vectorDatabase.databaseSpec',
    ),
    provider: required(text(item.provider), 'vectorDatabase.provider'),
    connectProps: isRecord(item.connectProps) ? item.connectProps : {},
    enabled: required(boolean(item.enabled), 'vectorDatabase.enabled'),
    ...(optionalDate(item.createdAt)
      ? { createdAt: optionalDate(item.createdAt) }
      : {}),
    ...(optionalDate(item.updatedAt)
      ? { updatedAt: optionalDate(item.updatedAt) }
      : {}),
  };
}
const action = (
  client: NocoBaseKnowledgeBaseClient,
  resource: string,
  name: string,
  options: ActionOptions = {},
) => client.action<unknown>(resource, name, { ...options, unwrap: 'none' });

const listQuery = (
  request: { mode: 'all' } | { mode: 'server'; page: number; pageSize: number },
) =>
  request.mode === 'all'
    ? { paginate: false }
    : { page: request.page, pageSize: request.pageSize };

const mapPagedResult = <T>(
  payload: unknown,
  fallback: { page: number; pageSize: number },
  mapper: (value: unknown) => T,
): PagedResult<T> => {
  const normalized = normalizePagedResult<unknown>(payload, fallback);
  return { ...normalized, rows: normalized.rows.map(mapper) };
};

const storageFromPayload = (payload: unknown): UploadStorage => {
  const value = responseData(payload);
  const storage = isRecord(value) ? value : {};
  const rules = isRecord(storage.rules) ? storage.rules : {};
  return {
    disk: required(text(storage.disk), 'uploadStorage.disk'),
    ...(text(storage.type) ? { type: text(storage.type) } : {}),
    ...(number(rules.size) !== undefined
      ? { maxFileSizeBytes: number(rules.size) }
      : {}),
  };
};

const extensionOf = (file: File) => {
  const dot = file.name.lastIndexOf('.');
  return dot < 0 ? '' : file.name.slice(dot).toLowerCase();
};

const cleanText = (value: unknown): string | undefined =>
  typeof value === 'string' && value.trim() ? value.trim() : undefined;

export function normalizeKnowledgeBaseMutation(
  values: KnowledgeBaseMutation,
  existing?: KnowledgeBase,
  visibleFields?: ReadonlySet<string>,
): KnowledgeBaseMutation {
  const include = (field: string): boolean =>
    !visibleFields || visibleFields.has(field);
  const normalized: KnowledgeBaseMutation = {
    ...(cleanText(values.key) ? { key: cleanText(values.key) } : {}),
    name: cleanText(values.name) ?? '',
    knowledgeBaseType: values.knowledgeBaseType,
    enabled: values.enabled !== false,
    ...(cleanText(values.description)
      ? { description: cleanText(values.description) }
      : {}),
  };
  const preserveOrSet = (field: keyof KnowledgeBaseMutation): void => {
    if (!include(String(field))) {
      const previous = existing?.[field as keyof KnowledgeBase];
      if (previous !== undefined)
        (normalized as Record<string, unknown>)[field] = previous;
      return;
    }
    const value = values[field];
    if (typeof value === 'string') {
      const cleaned = cleanText(value);
      if (cleaned) (normalized as Record<string, unknown>)[field] = cleaned;
    } else if (value !== undefined) {
      (normalized as Record<string, unknown>)[field] = value;
    }
  };
  for (const field of [
    'disk',
    'vectorDatabaseKey',
    'vectorStoreConfigKey',
    'llmService',
    'embeddingModel',
    'vectorStoreProvider',
    'vectorStoreProps',
    'segmentOptions',
  ] as const)
    preserveOrSet(field);
  return normalized;
}
export function normalizeVectorDatabaseMutation(
  values: VectorDatabaseMutation,
  existing?: VectorDatabase,
  visibleFields?: ReadonlySet<string>,
): VectorDatabaseMutation {
  const include = (field: string): boolean =>
    !visibleFields || visibleFields.has(field);
  const connectProps: Record<string, unknown> = {};
  const source = values.connectProps ?? {};
  for (const [key, raw] of Object.entries(source)) {
    if (!include(`connectProps.${key}`)) {
      if (existing?.connectProps[key] !== undefined)
        connectProps[key] = existing.connectProps[key];
      continue;
    }
    if (raw === '' || raw === undefined || raw === null) {
      if (existing?.connectProps[key] !== undefined)
        connectProps[key] = existing.connectProps[key];
      continue;
    }
    connectProps[key] = key === 'port' ? Number(raw) : raw;
  }
  if (!visibleFields && existing) {
    for (const [key, raw] of Object.entries(existing.connectProps)) {
      if (!(key in connectProps) && !(key in source)) connectProps[key] = raw;
    }
  }
  return {
    ...(cleanText(values.key) ? { key: cleanText(values.key) } : {}),
    name: cleanText(values.name) ?? '',
    provider: cleanText(values.provider) ?? '',
    ...(cleanText(values.databaseSpec)
      ? { databaseSpec: cleanText(values.databaseSpec) }
      : {}),
    connectProps,
    enabled: values.enabled !== false,
    ...(values.skipTableExistedCheck ? { skipTableExistedCheck: true } : {}),
  };
}

function toManagementOption(
  value: unknown,
  fallbackValueKeys: readonly string[] = ['value', 'name', 'key'],
): KnowledgeBaseManagementOption | undefined {
  const item = isRecord(value) ? value : {};
  const optionValue = fallbackValueKeys
    .map((key) => text(item[key]))
    .find(Boolean);
  const label =
    text(item.label) ?? text(item.title) ?? text(item.name) ?? optionValue;
  return optionValue && label ? { value: optionValue, label } : undefined;
}

export function createKnowledgeBaseService(
  client: NocoBaseKnowledgeBaseClient,
): KnowledgeBaseService {
  const getUploadStorage = async (
    knowledgeBaseKey: string,
    signal?: AbortSignal,
  ) =>
    storageFromPayload(
      await action(client, 'aiKnowledgeBaseDocs', 'getUploadStorage', {
        method: 'GET',
        query: { knowledgeBaseKey },
        signal,
      }),
    );

  return {
    async createKnowledgeBase(values) {
      return toKnowledgeBase(
        responseData(
          await action(client, 'aiKnowledgeBase', 'create', {
            method: 'POST',
            body: normalizeKnowledgeBaseMutation(values),
          }),
        ),
      );
    },
    async updateKnowledgeBase(id, values) {
      return toKnowledgeBase(
        responseData(
          await action(client, 'aiKnowledgeBase', 'update', {
            method: 'POST',
            query: { filterByTk: id },
            body: values,
          }),
        ),
      );
    },
    deleteKnowledgeBase: (id) =>
      action(client, 'aiKnowledgeBase', 'destroy', {
        method: 'POST',
        query: { 'filterByTk[]': [id] },
      }),
    async listKnowledgeBaseManagementOptions() {
      const [
        vectorsPayload,
        servicesPayload,
        storageDisksPayload,
        externalProvidersPayload,
      ] = await Promise.all([
        action(client, 'aiVectorDatabases', 'listEnabled', { method: 'GET' }),
        action(client, 'ai/ai', 'listLLMServices', {
          method: 'GET',
          query: { model: 'EMBEDDING' },
        }),
        action(client, 'aiKnowledgeBase', 'listStorageDisks', {
          method: 'GET',
        }),
        action(client, 'aiKnowledgeBase', 'listExternalVectorStoreProviders', {
          method: 'GET',
        }).catch(() => undefined),
      ]);
      const serviceValues = responseData(servicesPayload);
      const llmServices = (
        Array.isArray(serviceValues) ? serviceValues : []
      ).flatMap((value): KnowledgeBaseManagementOption[] => {
        const item = isRecord(value) ? value : {};
        const service = text(item.name);
        return service
          ? [{ value: service, label: text(item.title) ?? service }]
          : [];
      });
      const vectorValues = responseData(vectorsPayload);
      const vectorDatabases = (
        Array.isArray(vectorValues) ? vectorValues : []
      ).flatMap((value): KnowledgeBaseManagementOption[] => {
        const option = toManagementOption(value, ['key']);
        return option ? [option] : [];
      });
      const storageValues = responseData(storageDisksPayload);
      const storages = (
        Array.isArray(storageValues) ? storageValues : []
      ).flatMap((value): KnowledgeBaseManagementOption[] => {
        const option = toManagementOption(value, ['value']);
        return option ? [option] : [];
      });
      const externalProviderValues = responseData(externalProvidersPayload);
      const externalProviders = (
        Array.isArray(externalProviderValues) ? externalProviderValues : []
      ).flatMap((value): KnowledgeBaseManagementOption[] => {
        if (typeof value === 'string') return [{ value, label: value }];
        const option = toManagementOption(value);
        return option ? [option] : [];
      });
      return {
        vectorDatabases,
        llmServices,
        storages,
        externalProviders,
      } satisfies KnowledgeBaseManagementOptions;
    },
    async listEmbeddingModels(llmService) {
      const payload = responseData(
        await action(client, 'ai/ai', 'listModels', {
          method: 'GET',
          query: { llmService, model: 'EMBEDDING' },
        }),
      );
      if (!Array.isArray(payload)) return [];
      return payload.flatMap((value): KnowledgeBaseManagementOption[] => {
        const option = toManagementOption(value, ['id', 'value', 'name']);
        return option ? [option] : [];
      });
    },
    async listVectorDatabaseProviders() {
      const payload = responseData(
        await action(client, 'aiVectorDatabases', 'listProviders', {
          method: 'GET',
        }),
      );
      return Array.isArray(payload)
        ? payload
            .map(toVectorDatabaseProvider)
            .filter((item): item is VectorDatabaseProvider => !!item)
        : [];
    },
    async listVectorDatabases(request) {
      const payload = await action(client, 'aiVectorDatabases', 'list', {
        query: listQuery(request),
        signal: request.signal,
      });
      return mapPagedResult(
        payload,
        request.mode === 'all' ? { page: 1, pageSize: 20 } : request,
        toVectorDatabase,
      );
    },
    async getVectorDatabase(id, signal) {
      return toVectorDatabase(
        responseData(
          await action(client, 'aiVectorDatabases', 'get', {
            query: { filterByTk: id },
            signal,
          }),
        ),
      );
    },
    async createVectorDatabase(values) {
      return toVectorDatabase(
        responseData(
          await action(client, 'aiVectorDatabases', 'create', {
            method: 'POST',
            body: normalizeVectorDatabaseMutation(values),
          }),
        ),
      );
    },
    async updateVectorDatabase(id, values) {
      return toVectorDatabase(
        responseData(
          await action(client, 'aiVectorDatabases', 'update', {
            method: 'POST',
            query: { filterByTk: id },
            body: values,
          }),
        ),
      );
    },
    deleteVectorDatabase: (id) =>
      action(client, 'aiVectorDatabases', 'destroy', {
        method: 'POST',
        query: { 'filterByTk[]': [id] },
      }),
    async testVectorDatabaseConnection(values) {
      const payload = responseData(
        await action(client, 'aiVectorDatabases', 'testConnection', {
          method: 'POST',
          body: values,
        }),
      );
      const item = isRecord(payload) ? payload : {};
      return {
        success: boolean(item.success) === true,
        ...(text(item.error) ? { error: text(item.error) } : {}),
      };
    },
    async listEnabledVectorDatabases() {
      const payload = responseData(
        await action(client, 'aiVectorDatabases', 'listEnabled', {
          method: 'GET',
        }),
      );
      return Array.isArray(payload) ? payload.map(toVectorDatabase) : [];
    },
    async findRelatedKnowledgeBases(vectorDatabaseKey) {
      const payload = responseData(
        await action(client, 'aiVectorDatabases', 'findRelatedKnowledgeBase', {
          method: 'GET',
          query: { vectorDatabaseKey },
        }),
      );
      return Array.isArray(payload) ? payload.map(toKnowledgeBase) : [];
    },
    async listKnowledgeBases(request) {
      const payload = await action(client, 'aiKnowledgeBase', 'list', {
        query: {
          ...listQuery(request),
          ...(request.query
            ? { 'filter[name][$includes]': request.query }
            : {}),
        },
        signal: request.signal,
      });
      return mapPagedResult(
        payload,
        request.mode === 'all' ? { page: 1, pageSize: 20 } : request,
        toKnowledgeBase,
      );
    },

    async getKnowledgeBase(key, signal) {
      // The Live route uses the public knowledge-base key, while filterByTk targets the bigint primary key.
      const payload = await action(client, 'aiKnowledgeBase', 'list', {
        query: { paginate: false, 'filter[key]': key },
        signal,
      });
      const result = mapPagedResult(
        payload,
        { page: 1, pageSize: 1 },
        toKnowledgeBase,
      );
      const knowledgeBase = result.rows.find((item) => item.key === key);
      if (!knowledgeBase) {
        throw new Error('Knowledge base was not found or is not accessible.');
      }
      return knowledgeBase;
    },

    async listDocuments(request) {
      const payload = await action(client, 'aiKnowledgeBaseDocs', 'list', {
        query: {
          ...listQuery(request),
          'filter[knowledgeBaseKey]': request.knowledgeBaseKey,
          ...(request.query
            ? { 'filter[title][$includes]': request.query }
            : {}),
        },
        signal: request.signal,
      });
      return mapPagedResult(
        payload,
        request.mode === 'all' ? { page: 1, pageSize: 20 } : request,
        toDocument,
      );
    },

    async getDocument(request) {
      const document = toDocument(
        responseData(
          await action(client, 'aiKnowledgeBaseDocs', 'get', {
            query: { filterByTk: request.documentId },
            signal: request.signal,
          }),
        ),
      );
      if (document.knowledgeBaseKey !== request.knowledgeBaseKey) {
        throw new Error(
          'The returned document does not belong to the requested knowledge base.',
        );
      }
      return document;
    },

    async runRetrieval(request) {
      const payload = responseData(
        await action(client, 'aiKnowledgeBase', 'runHitTest', {
          method: 'POST',
          body: {
            knowledgeBaseKey: request.knowledgeBaseKey,
            query: request.query,
            topK: request.topK,
            score: request.score,
          },
          signal: request.signal,
        }),
      );
      return Array.isArray(payload) ? payload.map(toSearchResult) : [];
    },

    async listSegments(request) {
      const payload = await action(
        client,
        'aiKnowledgeBaseDocSegments',
        'list',
        {
          query: {
            ...listQuery(request),
            knowledgeBaseKey: request.knowledgeBaseKey,
            knowledgeBaseDocsId: request.documentId,
            ...(request.keyword ? { keyword: request.keyword } : {}),
            ...(request.enabled !== undefined
              ? { enabled: request.enabled }
              : {}),
          },
          signal: request.signal,
        },
      );
      return mapPagedResult(
        payload,
        request.mode === 'all' ? { page: 1, pageSize: 20 } : request,
        toSegment,
      );
    },

    async getSegment(request) {
      const payload = responseData(
        await action(client, 'aiKnowledgeBaseDocSegments', 'getSegment', {
          method: 'GET',
          query: {
            knowledgeBaseKey: request.knowledgeBaseKey,
            knowledgeBaseDocsId: request.documentId,
            segmentUid: request.segmentUid,
          },
          signal: request.signal,
        }),
      );
      return payload === undefined || payload === null
        ? undefined
        : toSegment(payload);
    },

    async getUploadConstraints(request): Promise<UploadConstraints> {
      const storage = await getUploadStorage(
        request.knowledgeBaseKey,
        request.signal,
      );
      return {
        acceptedExtensions: supportedExtensions,
        ...(storage.maxFileSizeBytes
          ? { maxFileSizeBytes: storage.maxFileSizeBytes }
          : {}),
      };
    },

    async getZipFilenameEncodingOptions(request) {
      const payload = responseData(
        await action(
          client,
          'aiKnowledgeBaseDocs',
          'getZipFilenameEncodingOptions',
          {
            method: 'GET',
            signal: request.signal,
          },
        ),
      );
      const result = isRecord(payload) ? payload : {};
      return Array.isArray(result.options)
        ? result.options.flatMap((option): ZipFilenameEncodingOption[] => {
            const item = isRecord(option) ? option : {};
            const value = text(item.value);
            const label = text(item.label);
            if (!value || !label) return [];
            return [
              {
                value,
                label,
                ...(text(item.description)
                  ? { description: text(item.description) }
                  : {}),
                ...(boolean(item.isDefault) !== undefined
                  ? { isDefault: boolean(item.isDefault) }
                  : {}),
              },
            ];
          })
        : [];
    },

    async uploadDocument(request): Promise<UploadResult> {
      const storage = await getUploadStorage(request.knowledgeBaseKey);
      if (
        storage.maxFileSizeBytes &&
        request.file.size > storage.maxFileSizeBytes
      ) {
        throw new Error('This file exceeds the server upload limit.');
      }
      if (!supportedExtensions.includes(extensionOf(request.file))) {
        throw new Error(
          `Unsupported file type: ${extensionOf(request.file) || 'no extension'}.`,
        );
      }

      let payload: unknown;
      if (storage.type === 's3-compatible') {
        const presigned = responseData(
          await action(client, 'storages', 'createPresignedUrl', {
            method: 'POST',
            body: {
              name: request.file.name,
              size: request.file.size,
              type: request.file.type,
              disk: storage.disk,
              storageType: storage.type,
            },
          }),
        );
        const upload = isRecord(presigned) ? presigned : {};
        const putUrl = text(upload.putUrl);
        const fileInfo = isRecord(upload.fileInfo) ? upload.fileInfo : {};
        if (!putUrl)
          throw new Error(
            'The upload service did not return a presigned upload URL.',
          );
        const put = await fetch(putUrl, {
          method: 'PUT',
          headers: request.file.type
            ? { 'Content-Type': request.file.type }
            : undefined,
          body: request.file,
        });
        if (!put.ok) throw new Error(`File upload failed (${put.status}).`);
        payload = await action(client, 'aiKnowledgeBaseDocs', 'upload', {
          method: 'POST',
          query: { knowledgeBaseKey: request.knowledgeBaseKey },
          body: {
            title: text(fileInfo.title) || request.file.name,
            filename: request.file.name,
            extname: text(fileInfo.extname) || extensionOf(request.file),
            path: required(text(fileInfo.key), 'presignedUpload.fileInfo.key'),
            size: number(fileInfo.size) ?? request.file.size,
            url: required(text(fileInfo.url), 'presignedUpload.fileInfo.url'),
            mimetype: text(fileInfo.mimetype) || request.file.type,
            disk: storage.disk,
            meta: {},
            ...(request.zipFilenameEncodings?.length
              ? { zipFilenameEncoding: request.zipFilenameEncodings }
              : {}),
          },
        });
      } else {
        const formData = new FormData();
        formData.append('knowledgeBaseKey', request.knowledgeBaseKey);
        for (const encoding of request.zipFilenameEncodings ?? []) {
          formData.append('zipFilenameEncoding[]', encoding);
        }
        formData.append('file', request.file);
        payload = await action(client, 'aiKnowledgeBaseDocs', 'upload', {
          method: 'POST',
          query: { knowledgeBaseKey: request.knowledgeBaseKey },
          body: formData,
        });
      }

      const result = responseData(payload);
      const record = isRecord(result) ? result : {};
      if (recordId(record.taskId) !== undefined) {
        return {
          taskId: recordId(record.taskId)!,
          ...(text(record.message) ? { message: text(record.message) } : {}),
        };
      }
      return toDocument(result);
    },

    vectorizeDocuments: ({ knowledgeBaseKey, documentIds }) =>
      action(client, 'aiKnowledgeBaseDocs', 'vectorization', {
        method: 'POST',
        query: {
          knowledgeBaseKey,
          ...(documentIds?.length ? { 'id[]': documentIds } : {}),
        },
      }),

    deleteDocuments: ({ documentIds }) =>
      action(client, 'aiKnowledgeBaseDocs', 'destroy', {
        method: 'POST',
        query: { 'filterByTk[]': documentIds },
      }),

    updateSegment: async ({ documentId, ...request }) =>
      toSegment(
        responseData(
          await action(client, 'aiKnowledgeBaseDocSegments', 'updateSegment', {
            method: 'POST',
            body: { ...request, knowledgeBaseDocsId: documentId },
          }),
        ),
      ),

    updateQuestions: async ({ documentId, ...request }) =>
      toSegment(
        responseData(
          await action(
            client,
            'aiKnowledgeBaseDocSegments',
            'updateQuestions',
            {
              method: 'POST',
              body: { ...request, knowledgeBaseDocsId: documentId },
            },
          ),
        ),
      ),

    setSegmentEnabled: async ({
      knowledgeBaseKey,
      documentId,
      segmentUid,
      enabled,
    }) =>
      toSegment(
        responseData(
          await action(client, 'aiKnowledgeBaseDocSegments', 'setEnabled', {
            method: 'POST',
            body: {
              knowledgeBaseKey,
              knowledgeBaseDocsId: documentId,
              segmentUid,
              enabled,
            },
          }),
        ),
      ),

    deleteSegment: ({ knowledgeBaseKey, documentId, segmentUid }) =>
      action(client, 'aiKnowledgeBaseDocSegments', 'deleteSegment', {
        method: 'POST',
        body: { knowledgeBaseKey, knowledgeBaseDocsId: documentId, segmentUid },
      }),

    regenerateSegments: ({ knowledgeBaseKey, documentId, segmentOptions }) =>
      action(client, 'aiKnowledgeBaseDocSegments', 'regenerate', {
        method: 'POST',
        body: {
          knowledgeBaseKey,
          knowledgeBaseDocsId: documentId,
          ...(segmentOptions ? { segmentOptions } : {}),
        },
      }),
  };
}

import type { PagedResult } from '../utils.js';
import type {
  PagedRequestMode,
  DocumentListRequest,
  KnowledgeBase,
