/**
 * Data contract for NocoBase AI Knowledge Base user-side actions. The default adapter
 * intentionally excludes administrator vector-store and configuration actions.
 * Server-side authorization and positive response projection remain authoritative.
 */
export interface KnowledgeBaseService {
  createKnowledgeBase(values: KnowledgeBaseMutation): Promise<KnowledgeBase>;
  updateKnowledgeBase(
    id: RecordId,
    values: Partial<KnowledgeBaseMutation>,
  ): Promise<KnowledgeBase>;
  deleteKnowledgeBase(id: RecordId): Promise<unknown>;
  listKnowledgeBaseManagementOptions(): Promise<KnowledgeBaseManagementOptions>;
  listEmbeddingModels(
    llmService: string,
  ): Promise<KnowledgeBaseManagementOption[]>;
  listVectorDatabaseProviders(): Promise<VectorDatabaseProvider[]>;
  listVectorDatabases(
    request: PagedRequestMode & { signal?: AbortSignal },
  ): Promise<PagedResult<VectorDatabase>>;
  getVectorDatabase(
    id: RecordId,
    signal?: AbortSignal,
  ): Promise<VectorDatabase>;
  createVectorDatabase(values: VectorDatabaseMutation): Promise<VectorDatabase>;
  updateVectorDatabase(
    id: RecordId,
    values: Partial<VectorDatabaseMutation>,
  ): Promise<VectorDatabase>;
  deleteVectorDatabase(id: RecordId): Promise<unknown>;
  testVectorDatabaseConnection(
    values: Pick<VectorDatabaseMutation, 'provider' | 'connectProps'>,
  ): Promise<{ success: boolean; error?: string }>;
  listEnabledVectorDatabases(): Promise<VectorDatabase[]>;
  findRelatedKnowledgeBases(
    vectorDatabaseKey: string,
  ): Promise<KnowledgeBase[]>;
  listKnowledgeBases(
    request: PagedRequestMode & { query?: string; signal?: AbortSignal },
  ): Promise<PagedResult<KnowledgeBase>>;
  getKnowledgeBase(key: string, signal?: AbortSignal): Promise<KnowledgeBase>;
  listDocuments(
    request: DocumentListRequest,
  ): Promise<PagedResult<KnowledgeBaseDocument>>;
  getDocument(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    signal?: AbortSignal;
  }): Promise<KnowledgeBaseDocument>;
  runRetrieval(request: RetrievalRequest): Promise<KnowledgeBaseSearchResult[]>;
  listSegments(
    request: SegmentListRequest,
  ): Promise<PagedResult<KnowledgeBaseSegment>>;
  getSegment(
    request: SegmentRequest,
  ): Promise<KnowledgeBaseSegment | undefined>;

  /** Safe capability payload only: extensions and size, never storage/provider configuration. */
  getUploadConstraints(request: {
    knowledgeBaseKey: string;
    signal?: AbortSignal;
  }): Promise<UploadConstraints>;
  /** Request only after a ZIP is selected; an empty selection must remain omitted from upload. */
  getZipFilenameEncodingOptions(request: {
    knowledgeBaseKey: string;
    signal?: AbortSignal;
  }): Promise<ZipFilenameEncodingOption[]>;
  /**
   * The adapter owns multipart/S3 branching. Multipart must include knowledgeBaseKey
   * in both the query and FormData; an S3 finalize payload must be flat.
   */
  uploadDocument(request: {
    knowledgeBaseKey: string;
    file: File;
    zipFilenameEncodings?: string[];
  }): Promise<UploadResult>;

  vectorizeDocuments(request: {
    knowledgeBaseKey: string;
    documentIds?: RecordId[];
  }): Promise<unknown>;
  deleteDocuments(request: { documentIds: RecordId[] }): Promise<unknown>;
  updateSegment(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    segmentUid: string;
    title?: string;
    content: string;
    contentHash: string;
  }): Promise<KnowledgeBaseSegment>;
  updateQuestions(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    segmentUid: string;
    questions: KnowledgeBaseSegment['questions'];
    contentHash: string;
  }): Promise<KnowledgeBaseSegment>;
  setSegmentEnabled(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    segmentUid: string;
    enabled: boolean;
  }): Promise<KnowledgeBaseSegment>;
  deleteSegment(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    segmentUid: string;
  }): Promise<unknown>;
  regenerateSegments(request: {
    knowledgeBaseKey: string;
    documentId: RecordId;
    segmentOptions?: KnowledgeBaseSegmentOptions;
  }): Promise<unknown>;
}

export type KnowledgeBaseType = 'LOCAL' | 'READONLY' | 'EXTERNAL';
export type RecordId = string | number;

/**
 * User-side shape. Its fields are a positive allowlist that the Portal server
 * adapter must project before data reaches this package; a TypeScript type is
 * not itself a security boundary.
 */
export type KnowledgeBase = {
  id: RecordId;
  key: string;
  name: string;
  description?: string;
  knowledgeBaseType: KnowledgeBaseType;
  documentCount?: number;
  characterCount?: number;
  aiEmployeeCount?: number;
  enabled: boolean;
  vectorStoreProvider?: string;
  vectorStoreConfigKey?: string;
  vectorDatabaseKey?: string;
  disk?: string;
  llmService?: string;
  embeddingModel?: string;
  vectorStoreProps?: Array<{ name?: string; key: string; value: unknown }>;
  segmentOptions?: KnowledgeBaseSegmentOptions;
  createdAt?: string;
  updatedAt?: string;
};

export type KnowledgeBaseSegmentOptions = {
  enabled?: boolean;
  chunkSize?: number;
  chunkOverlap?: number;
};
export type KnowledgeBaseDocument = {
  id: RecordId;
  key?: string;
  title?: string;
  filename?: string;
  extname?: string;
  size?: number;
  mimetype?: string;
  /** Server-issued file URL. Resolve it against the NocoBase origin and fetch it with the active auth headers. */
  url?: string;
  preview?: string;
  knowledgeBaseKey: string;
  characterCount?: number;
  segmentCount?: number;
  segmentOptions?: KnowledgeBaseSegmentOptions;
  segmentStatus?: string;
  segmentErrorMessage?: string;
  segmentUpdatedAt?: string;
  enabled?: boolean;
  indexStatus?: string;
  errorMessage?: string;
  accessAbility?: 'readOnly' | 'readWrite';
  createdById?: RecordId;
  createdAt?: string;
  updatedAt?: string;
};

/** Search metadata must be explicitly modeled by an application before it is rendered. */
export type KnowledgeBaseSearchResult = {
  id?: RecordId;
  title?: string;
  filename?: string;
  content?: string;
  score?: number;
  matchedQuestions?: string[];
};

export type KnowledgeBaseSegmentQuestion = {
  id?: RecordId;
  content: string;
  enabled?: boolean;
  hash?: string;
};

export type KnowledgeBaseSegment = {
  uid: string;
  position?: number;
  title?: string;
  preview?: string;
  content?: string;
  charLength?: number;
  questionCount?: number;
  enabled?: boolean;
  contentHash?: string;
  updatedAt?: string;
  questions?: KnowledgeBaseSegmentQuestion[];
};

export type ZipFilenameEncodingOption = {
  value: string;
  label: string;
  description?: string;
  isDefault?: boolean;
};

export type UploadConstraints = {
  acceptedExtensions?: string[];
  maxFileSizeBytes?: number;
};

export type UploadResult =
  KnowledgeBaseDocument | { taskId: RecordId; message?: string };

export type PagedRequestMode =
  { mode: 'all' } | { mode: 'server'; page: number; pageSize: number };

export type KnowledgeBaseListRequest = PagedRequestMode & {
  query?: string;
  signal?: AbortSignal;
};

export type DocumentListRequest = PagedRequestMode & {
  knowledgeBaseKey: string;
  query?: string;
  signal?: AbortSignal;
};

export type SegmentListRequest = PagedRequestMode & {
  knowledgeBaseKey: string;
  documentId: RecordId;
  keyword?: string;
